(5015358, 732029, 42601, '<td valign="top">Nice composition and capture. The OOF logs/twigs in the bottom right hand corner catches my eye a little.</td>', 'Nice composition and capture. The OOF logs/twigs in the bottom right hand corner catches my eye a little.', '2008-10-20 02:22:31.000000', NULL, 1),
(5015359, 731937, 42601, '<td valign="top">My first impression was - nicely done. However the more I look at it, the further away from "wildlife" my mind goes. It stands strong as a symbol, yet not sure as a topic contender.</td>', 'My first impression was - nicely done. However the more I look at it, the further away from "wildlife" my mind goes. It stands strong as a symbol, yet not sure as a topic contender.', '2008-10-20 02:25:03.000000', NULL, 1),
(5015360, 732013, 42601, '<td valign="top">Okay, composition is everything here. We have two subjects that are cut off/cropped in a seemingly nice background. It may have been better to focus on one with the fenceline. Also, look at your contrast/curves to bring some of the highlights down and sharpen up your subjects.</td>', 'Okay, composition is everything here. We have two subjects that are cut off/cropped in a seemingly nice background. It may have been better to focus on one with the fenceline. Also, look at your contrast/curves to bring some of the highlights down and sharpen up your subjects.', '2008-10-20 02:26:35.000000', NULL, 1),
(5015363, 731548, 42601, '<td valign="top">Nice shot. Poor Froggy''s toast! I like the capture, but the crop behind the bird is a little distracting for me.</td>', 'Nice shot. Poor Froggy''s toast! I like the capture, but the crop behind the bird is a little distracting for me.', '2008-10-20 02:27:32.000000', NULL, 1),
(5015374, 732152, 97635, '<td valign="top">Now that is a ride I remember and not a bad loooking toad either, I love this photo. I give it a 10</td>', 'Now that is a ride I remember and not a bad loooking toad either, I love this photo. I give it a 10', '2008-10-20 02:52:23.000000', NULL, 1),
