(5015437, 732262, 42601, '<td valign="top">Awesome capture, brilliant crop. I love this, hope it does well.</td>', 'Awesome capture, brilliant crop. I love this, hope it does well.', '2008-10-20 03:19:50.000000', NULL, 1),
(5015443, 731585, 42601, '<td valign="top">Overall it feels a little dull for me. The blues in the background aren''t appealing, and the crop on the body of the swan doesnt really lend toward anything. In my opinion, the head of a swan isn''t its most beautiful feature, so perhaps look at exploiting other areas of your subject. Good luck!</td>', 'Overall it feels a little dull for me. The blues in the background aren''t appealing, and the crop on the body of the swan doesnt really lend toward anything. In my opinion, the head of a swan isn''t its most beautiful feature, so perhaps look at exploiting other areas of your subject. Good luck!', '2008-10-20 03:22:08.000000', NULL, 1),
(5015446, 730572, 42601, '<td valign="top">I''m not a fan of this sort of thing, but for technical aspects i''d say the head is a little out of focus and "dirty" around the eyes which couldve been looked at.</td>', 'I''m not a fan of this sort of thing, but for technical aspects i''d say the head is a little out of focus and "dirty" around the eyes which couldve been looked at.', '2008-10-20 03:23:36.000000', NULL, 1),
(5015449, 732072, 42601, '<td valign="top">Nice pose, however your processing needs a lot of work. There is a white bar on the right hand side of the photo which is very distracting. Also, I believe you can play a lot with the saturation and curves to create a more appealing effect.</td>', 'Nice pose, however your processing needs a lot of work. There is a white bar on the right hand side of the photo which is very distracting. Also, I believe you can play a lot with the saturation and curves to create a more appealing effect.', '2008-10-20 03:24:48.000000', NULL, 1),
(5015450, 732299, 42601, '<td valign="top">Yup, there we go. This will do well.</td>', 'Yup, there we go. This will do well.', '2008-10-20 03:25:40.000000', NULL, 1),
(5015452, 731542, 42601, '<td valign="top">I like the open shot, however you couldve easily cropped off the distracting thing on the bottom right hand of the photo. Also, your colours seem a little faded - a play with contrast/curves/shadow/highlight could fix.</td>', 'I like the open shot, however you couldve easily cropped off the distracting thing on the bottom right hand of the photo. Also, your colours seem a little faded - a play with contrast/curves/shadow/highlight could fix.', '2008-10-20 03:27:16.000000', NULL, 1),
