(5015725, 731937, 15711, '<td valign="top">Really pretty but I''m afraid this type of editing might not do well on DPC.  Maybe I''m wrong. :~)  I like it - very artful. 7</td>', 'Really pretty but I''m afraid this type of editing might not do well on DPC.  Maybe I''m wrong. :~)  I like it - very artful. 7', '2008-10-20 09:59:28.000000', NULL, 1),
(5015726, 732244, 39880, '<td valign="top">This is a good shot, I like it.  Now for one minor nitpick, very minor.  The speck between the front birds legs, clone it out.  With that said, this is still one of my highest scores.</td>', 'This is a good shot, I like it.  Now for one minor nitpick, very minor.  The speck between the front birds legs, clone it out.  With that said, this is still one of my highest scores.', '2008-10-20 09:59:45.000000', NULL, 1),
(5015727, 732230, 82064, '<td valign="top">Black and white is perfect for this shot. Good title for the expression and pose of the bird.</td>', 'Black and white is perfect for this shot. Good title for the expression and pose of the bird.', '2008-10-20 09:59:46.000000', NULL, 1),
