(5016167, 732163, 3087, '<td valign="top">Nice diagonal comp. Great detail, especially in that eye.</td>', 'Nice diagonal comp. Great detail, especially in that eye.', '2008-10-20 14:07:58.000000', NULL, 1),
(5016168, 732247, 3087, '<td valign="top">Ha, looks like an army descending on me! Great low-down perspective!</td>', 'Ha, looks like an army descending on me! Great low-down perspective!', '2008-10-20 14:08:27.000000', NULL, 1),
