(5016896, 732188, 11854, '<td valign="top">Fantastic job on the selective desat! Love the chaos! 10</td>', 'Fantastic job on the selective desat! Love the chaos! 10', '2008-10-20 19:10:51.000000', NULL, 1),
(5016897, 732232, 75713, '<td valign="top">Coming back to comment:<br/> <br/>I like the painterly effect of your photo.. and think that gulls are under appreciated as they are truly beautiful birds and so graceful in flight.. I like the grain in this shot and the soft muted tone.. it looks like you bumped the colors up a fair bit and that worked well with the blue and the yellow..but not as well with the red -  the red in the bird''s feet, it''s beak and whatever it is holding in it''s mouth look a bit off, maybe taking the red down a bit in your pp would have been a better choice, keeping true to the painterly effects the rest of your photo has.</td>', 'Coming back to comment: I like the painterly effect of your photo.. and think that gulls are under appreciated as they are truly beautiful birds and so graceful in flight.. I like the grain in this shot and the soft muted tone.. it looks like you bumped the colors up a fair bit and that worked well with the blue and the yellow..but not as well with the red -  the red in the bird''s feet, it''s beak and whatever it is holding in it''s mouth look a bit off, maybe taking the red down a bit in your pp would have been a better choice, keeping true to the painterly effects the rest of your photo has.', '2008-10-20 19:11:19.000000', NULL, 1),
(5016898, 731583, 11854, '<td valign="top">The best of the eagle shots in the challenge. Excellent color and clarity! 10</td>', 'The best of the eagle shots in the challenge. Excellent color and clarity! 10', '2008-10-20 19:11:21.000000', NULL, 1),
