(5016971, 732135, 11854, '<td valign="top">WOw! THe lines of the animal against the lines (and colors) of the rock face are outstanding! Love the shadow. Excellent clarity (you must have one heck of a zoom).</td>', 'WOw! THe lines of the animal against the lines (and colors) of the rock face are outstanding! Love the shadow. Excellent clarity (you must have one heck of a zoom).', '2008-10-20 19:52:34.000000', NULL, 1),
(5016973, 731942, 11854, '<td valign="top">Beautiful processing! The eyes are just a touch too soft, but it''s still fabulous!</td>', 'Beautiful processing! The eyes are just a touch too soft, but it''s still fabulous!', '2008-10-20 19:53:15.000000', NULL, 1),
(5016976, 731868, 11854, '<td valign="top">Beautiful and majestic!</td>', 'Beautiful and majestic!', '2008-10-20 19:53:44.000000', NULL, 1),
(5016977, 732094, 11854, '<td valign="top">Wow! His feathers are standing on end (on his head). LOL! Nice pose and wonderful clarity!</td>', 'Wow! His feathers are standing on end (on his head). LOL! Nice pose and wonderful clarity!', '2008-10-20 19:54:31.000000', NULL, 1),
(5016978, 732252, 11854, '<td valign="top">Aawww! This is so cute!</td>', 'Aawww! This is so cute!', '2008-10-20 19:54:56.000000', NULL, 1),
(5016979, 731619, 11854, '<td valign="top">Fantastic detail on that eye!!</td>', 'Fantastic detail on that eye!!', '2008-10-20 19:55:11.000000', NULL, 1),
(5016981, 730572, 11854, '<td valign="top">Sparrows are just so dog gone cute! Love the soft border you went with.</td>', 'Sparrows are just so dog gone cute! Love the soft border you went with.', '2008-10-20 19:55:49.000000', NULL, 1),
(5016982, 732247, 11854, '<td valign="top">Wow! Ready for either a rumble or a dance off! LOL! Great catch!</td>', 'Wow! Ready for either a rumble or a dance off! LOL! Great catch!', '2008-10-20 19:56:16.000000', NULL, 1),
