(5017027, 731798, 11854, '<td valign="top">This is one of the lightest colored flamingo''s I''ve ever seen. Very pretty pink tone. Great detail!</td>', 'This is one of the lightest colored flamingo''s I''ve ever seen. Very pretty pink tone. Great detail!', '2008-10-20 20:28:29.000000', NULL, 1),
(5017028, 731886, 36382, '<td valign="top">I''m giving this high marks.  I love the tones.  Nice choice to go black and white.  The pose and framing is perfect.</td>', 'I''m giving this high marks.  I love the tones.  Nice choice to go black and white.  The pose and framing is perfect.', '2008-10-20 20:30:39.000000', NULL, 1),
