INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5017080, 730790, 75713, '<td valign="top">Now that''s a well fed squirrel!  I really like the sdof, your eyes are brought right to the squirrels head and your crisp focus makes it just pop - love the catch light in the eyes, gives it such personality.. looks like it should be an illustration in a children''s book - an excellent photo, suits the challenge perfectly - bumping the score right up!</td>', 'Now that''s a well fed squirrel!  I really like the sdof, your eyes are brought right to the squirrels head and your crisp focus makes it just pop - love the catch light in the eyes, gives it such personality.. looks like it should be an illustration in a children''s book - an excellent photo, suits the challenge perfectly - bumping the score right up!', '2008-10-20 21:15:16.000000', NULL, 1),
(5017081, 732208, 51597, '<td valign="top">Cool Shot!!</td>', 'Cool Shot!!', '2008-10-20 21:15:52.000000', NULL, 1),
