(5018039, 732135, 88136, '<td valign="top">WOW! this is so cool! the rocks look incredible, the shadow is perfect, and the red foliage adds just the perfect amount of color. superb!</td>', 'WOW! this is so cool! the rocks look incredible, the shadow is perfect, and the red foliage adds just the perfect amount of color. superb!', '2008-10-21 14:14:18.000000', NULL, 1),
(5018040, 731880, 60495, '<td valign="top">The fall colors in the water really make the shot, nicely done.</td>', 'The fall colors in the water really make the shot, nicely done.', '2008-10-21 14:14:37.000000', NULL, 1),
(5018042, 731548, 88136, '<td valign="top">i like the water drops and the frog the most out of this photo. maybe a little dodging and burning could have accented certain areas of this</td>', 'i like the water drops and the frog the most out of this photo. maybe a little dodging and burning could have accented certain areas of this', '2008-10-21 14:15:26.000000', NULL, 1),
