(5018113, 732094, 35994, '<td valign="top">Nice detail! The colors are really nice, I like the crop too.</td>', 'Nice detail! The colors are really nice, I like the crop too.', '2008-10-21 14:36:35.000000', NULL, 1),
(5018120, 732201, 35994, '<td valign="top">Love the soft vignette, it really draws your attention in nicely. I''m going to make a guess &amp; say this is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=67145" rel="nofollow" target="_blank">roz</a>?</td>', 'Love the soft vignette, it really draws your attention in nicely. I''m going to make a guess & say this is  roz?', '2008-10-21 14:40:46.000000', NULL, 1);
