(5018761, 732134, 65234, '<td valign="top">Looks like someone''s pet asleep on the lawn!  Might have more interest from another angle, or cropped considerably closer.</td>', 'Looks like someone''s pet asleep on the lawn!  Might have more interest from another angle, or cropped considerably closer.', '2008-10-21 18:44:02.000000', NULL, 1),
(5018763, 732247, 7810, '<td valign="top">This is an awesome pic (straight to favs) ...either a long lens or you have food strapped to your camera :D<br/> <br/>Love it either way  10</td>', 'This is an awesome pic (straight to favs) ...either a long lens or you have food strapped to your camera :D Love it either way  10', '2008-10-21 18:44:46.000000', NULL, 1),
