(5019795, 732273, 98073, '<td valign="top">I would like to see more clarity of the head rather than the bottom of the photo.  Love your choice though.</td>', 'I would like to see more clarity of the head rather than the bottom of the photo.  Love your choice though.', '2008-10-22 04:08:39.000000', NULL, 1),
(5019796, 732014, 98073, '<td valign="top">I am enjoying the black and white.  It portrays a mood of forthcoming winter to me.  The light on your subject gives life to the photo.  Well done.</td>', 'I am enjoying the black and white.  It portrays a mood of forthcoming winter to me.  The light on your subject gives life to the photo.  Well done.', '2008-10-22 04:08:51.000000', NULL, 1),
(5019797, 731169, 98073, '<td valign="top">Well done, I can feel the heat from here.</td>', 'Well done, I can feel the heat from here.', '2008-10-22 04:09:07.000000', NULL, 1),
(5019801, 732184, 98073, '<td valign="top">Love it, my guess is he is looking out from behind a tree?  Great shot.</td>', 'Love it, my guess is he is looking out from behind a tree?  Great shot.', '2008-10-22 04:09:36.000000', NULL, 1),
(5019802, 732121, 98073, '<td valign="top">I like the subject, but feel its been over lightened?</td>', 'I like the subject, but feel its been over lightened?', '2008-10-22 04:09:38.000000', NULL, 1),
(5019803, 731663, 98073, '<td valign="top">Wish "I" had taken this shot.  LOVE IT.</td>', 'Wish "I" had taken this shot.  LOVE IT.', '2008-10-22 04:10:00.000000', NULL, 1),
(5019805, 732188, 98073, '<td valign="top">I enjoy the way you have highlighted the centre bird with the red.  Well done.</td>', 'I enjoy the way you have highlighted the centre bird with the red.  Well done.', '2008-10-22 04:11:07.000000', NULL, 1),
(5019807, 732297, 98073, '<td valign="top">Well done.  Very refreshing.</td>', 'Well done.  Very refreshing.', '2008-10-22 04:11:31.000000', NULL, 1),
(5019809, 731582, 98073, '<td valign="top">Well balanced.</td>', 'Well balanced.', '2008-10-22 04:11:47.000000', NULL, 1),
(5019811, 731765, 98073, '<td valign="top">So cool to look at.  Thanks for submitting this.</td>', 'So cool to look at.  Thanks for submitting this.', '2008-10-22 04:12:15.000000', NULL, 1),
(5019998, 731886, 71550, '<td valign="top">Hope to see this on the home page. 10</td>', 'Hope to see this on the home page. 10', '2008-10-22 08:05:27.000000', NULL, 1),
(5020092, 732220, 70270, '<td valign="top">Great creative subject for the challenge, and excellent control of lighting and glare.  9</td>', 'Great creative subject for the challenge, and excellent control of lighting and glare.  9', '2008-10-22 09:20:33.000000', NULL, 1),
(5020093, 731582, 70270, '<td valign="top">Great capture!  Good luck.  8</td>', 'Great capture!  Good luck.  8', '2008-10-22 09:22:43.000000', NULL, 1),
(5020096, 732075, 70270, '<td valign="top">Great eye, love the repeating forms here, and a nice job of capturing the pigeon in its natural environment.  Good luck.  8</td>', 'Great eye, love the repeating forms here, and a nice job of capturing the pigeon in its natural environment.  Good luck.  8', '2008-10-22 09:23:24.000000', NULL, 1),
(5020101, 732247, 70270, '<td valign="top">My favorite in the challenge, wonderful use of DOF and an excellent capture of a difficult subject.  10</td>', 'My favorite in the challenge, wonderful use of DOF and an excellent capture of a difficult subject.  10', '2008-10-22 09:27:04.000000', NULL, 1),
(5020107, 731880, 30791, '<td valign="top">wow thats so pretty</td>', 'wow thats so pretty', '2008-10-22 09:33:09.000000', NULL, 1),
(5020108, 731765, 30791, '<td valign="top">GOJIRA!!!</td>', 'GOJIRA!!!', '2008-10-22 09:33:20.000000', NULL, 1),
(5020110, 731020, 30791, '<td valign="top">awww turtles get extra points<br/>9!</td>', 'awww turtles get extra points9!', '2008-10-22 09:34:26.000000', NULL, 1),
(5020122, 731649, 54446, '<td valign="top">Came back and bumped this up to a "9".  Great composition.  Amazing exposure of the white feathers in the sunlight.  A superb natural environment.  The bird is in action with movement captured crisply.  Just overall a very fine wildlife/nature image.  Great work!</td>', 'Came back and bumped this up to a "9".  Great composition.  Amazing exposure of the white feathers in the sunlight.  A superb natural environment.  The bird is in action with movement captured crisply.  Just overall a very fine wildlife/nature image.  Great work!', '2008-10-22 09:42:17.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5020175, 732230, 10878, '<td valign="top">I really like the composition here.</td>', 'I really like the composition here.', '2008-10-22 10:16:22.000000', NULL, 1),
(5020234, 732014, 65234, '<td valign="top">Adorable little bird with nice detail.  Looks good in B&amp;W.  Maybe needed a touch more DOF or the focal point shifted, as the leaves on the lower left look sharper to me than the bird''s head.</td>', 'Adorable little bird with nice detail.  Looks good in B&W.  Maybe needed a touch more DOF or the focal point shifted, as the leaves on the lower left look sharper to me than the bird''s head.', '2008-10-22 11:05:17.000000', NULL, 1),
(5020238, 732118, 65234, '<td valign="top">She looks bored.  Nice fill-the-frame sort of composition.  Could use a little more DOF as the end of the muzzle doesn''t look sharply focussed, and since there''s some expression there with the cud-chewing (or talking, if it''s a magical beast) I find myself wanting sharpness there, too.  Also maybe dodge the eyes a little to bring out the detail there.</td>', 'She looks bored.  Nice fill-the-frame sort of composition.  Could use a little more DOF as the end of the muzzle doesn''t look sharply focussed, and since there''s some expression there with the cud-chewing (or talking, if it''s a magical beast) I find myself wanting sharpness there, too.  Also maybe dodge the eyes a little to bring out the detail there.', '2008-10-22 11:07:59.000000', NULL, 1),
(5020253, 732214, 65234, '<td valign="top">I''d have been thrilled to stumble upon this majestic fellow!!  I''m guessing he didn''t give you a chance for too many shots and he''s well-camouflaged with his color and the similarities between his antlers and surrounding branches, so I''d do a bit more processing to bring him out better.  Less saturation in the surroundings, clone out the OOF foreground leaves, maybe dodge him some and gently blur the background.  Also dodge his eye to find a catchlight.  But finding him and getting the shot was the hard part ;-)</td>', 'I''d have been thrilled to stumble upon this majestic fellow!!  I''m guessing he didn''t give you a chance for too many shots and he''s well-camouflaged with his color and the similarities between his antlers and surrounding branches, so I''d do a bit more processing to bring him out better.  Less saturation in the surroundings, clone out the OOF foreground leaves, maybe dodge him some and gently blur the background.  Also dodge his eye to find a catchlight.  But finding him and getting the shot was the hard part ;-)', '2008-10-22 11:13:27.000000', NULL, 1),
(5020261, 732029, 65234, '<td valign="top">Lovely bird, nice job on the exposure and I like the feathers blowing in the breeze.  DOF strikes me as a little odd in the foreground as it seems to be uniformly OOF and then suddenly in-focus at the shoreline, rather than a gradual change.  Could be a trick of the angles of the camera and the shore.</td>', 'Lovely bird, nice job on the exposure and I like the feathers blowing in the breeze.  DOF strikes me as a little odd in the foreground as it seems to be uniformly OOF and then suddenly in-focus at the shoreline, rather than a gradual change.  Could be a trick of the angles of the camera and the shore.', '2008-10-22 11:16:50.000000', NULL, 1),
(5020263, 731716, 65234, '<td valign="top">Nice variation in their postures for the silhouettes.</td>', 'Nice variation in their postures for the silhouettes.', '2008-10-22 11:17:45.000000', NULL, 1),
(5020268, 731880, 65234, '<td valign="top">The water is quite striking!  Bird also has nice detail and you caught him admiring his own reflection.  The water actually grabs my attention more than the seagull but his colors are different enough that he''s not completely overwhelmed by his surroundings.  Not sure I like the centered crop.</td>', 'The water is quite striking!  Bird also has nice detail and you caught him admiring his own reflection.  The water actually grabs my attention more than the seagull but his colors are different enough that he''s not completely overwhelmed by his surroundings.  Not sure I like the centered crop.', '2008-10-22 11:20:38.000000', NULL, 1),
(5020271, 731714, 65234, '<td valign="top">Oooh, fire water!  I like the diagonal to the composition, too, and the detail and exposure.  I think he needs a little more room on the left, though, as the image feels crowded there.</td>', 'Oooh, fire water!  I like the diagonal to the composition, too, and the detail and exposure.  I think he needs a little more room on the left, though, as the image feels crowded there.', '2008-10-22 11:22:04.000000', NULL, 1),
(5020277, 731919, 65234, '<td valign="top">He looks a bit pouffy.  I don''t think I''ve seen one in a tree before, only wading or flying, so I''m enjoying the perspective.  I might have cropped a bit tighter on top and the right.</td>', 'He looks a bit pouffy.  I don''t think I''ve seen one in a tree before, only wading or flying, so I''m enjoying the perspective.  I might have cropped a bit tighter on top and the right.', '2008-10-22 11:24:10.000000', NULL, 1),
(5020284, 732150, 65234, '<td valign="top">Great light and color palette.  If I could I''d step a few paces to the left so all his antlers had a leafy background.</td>', 'Great light and color palette.  If I could I''d step a few paces to the left so all his antlers had a leafy background.', '2008-10-22 11:25:56.000000', NULL, 1),
(5020289, 732121, 65234, '<td valign="top">Nice capture with his mouth open, even if he is only munching on a stick.  He still looks formidable.  Contrast is a little strong but he''s a harsh sort of creature so that''s OK.  I''d clone out the bright spot on the upper right.</td>', 'Nice capture with his mouth open, even if he is only munching on a stick.  He still looks formidable.  Contrast is a little strong but he''s a harsh sort of creature so that''s OK.  I''d clone out the bright spot on the upper right.', '2008-10-22 11:27:28.000000', NULL, 1),
(5020295, 732301, 65234, '<td valign="top">Wow; very cool moment to freeze!  Looks like there were some leaves on the left very close to the camera; sometimes a bit of burning and colorizing can compensate for that, particularly on the tree trunk and other bird.  Otherwise I might settle for a closer crop.</td>', 'Wow; very cool moment to freeze!  Looks like there were some leaves on the left very close to the camera; sometimes a bit of burning and colorizing can compensate for that, particularly on the tree trunk and other bird.  Otherwise I might settle for a closer crop.', '2008-10-22 11:29:58.000000', NULL, 1),
(5020300, 731649, 65234, '<td valign="top">Beautiful wing position you captured!  I might prefer more shallow DOF so the surrounding grasses were blurred out some, but that may not have been an option depending on how far away you were.</td>', 'Beautiful wing position you captured!  I might prefer more shallow DOF so the surrounding grasses were blurred out some, but that may not have been an option depending on how far away you were.', '2008-10-22 11:31:33.000000', NULL, 1),
(5020303, 732181, 65234, '<td valign="top">Adorable stereotypical squirrel pose, and his red color stands out nicely on the gray stump.  I''d crop/clone out the closer tree bits on the far left.</td>', 'Adorable stereotypical squirrel pose, and his red color stands out nicely on the gray stump.  I''d crop/clone out the closer tree bits on the far left.', '2008-10-22 11:32:52.000000', NULL, 1),
(5020304, 732278, 65234, '<td valign="top">Gawd, those are not pretty birds!  Nonetheless you captured enough detail in the eye to make him seem like there''s a soul in there.  Nice portrait, really.</td>', 'Gawd, those are not pretty birds!  Nonetheless you captured enough detail in the eye to make him seem like there''s a soul in there.  Nice portrait, really.', '2008-10-22 11:34:30.000000', NULL, 1),
(5020305, 732280, 65234, '<td valign="top">Cute pose and I like the bits of white I see in the examining bird''s eye.  Really adds a lot of expression to this.  Of course, I may never drink out of a public water fountain again!</td>', 'Cute pose and I like the bits of white I see in the examining bird''s eye.  Really adds a lot of expression to this.  Of course, I may never drink out of a public water fountain again!', '2008-10-22 11:35:30.000000', NULL, 1),
(5020369, 732281, 99263, '<td valign="top">Lovely shot and great setting with all those beautiful colors.</td>', 'Lovely shot and great setting with all those beautiful colors.', '2008-10-22 12:33:32.000000', NULL, 1),
(5020372, 730572, 99263, '<td valign="top">Wonderful capture.I love the pose of the little bird and the minimalistic background has just the right amount of dof.</td>', 'Wonderful capture.I love the pose of the little bird and the minimalistic background has just the right amount of dof.', '2008-10-22 12:36:42.000000', NULL, 1),
(5020387, 732297, 99263, '<td valign="top">Splendid capture that exudes a feeling of great tranquility. Maybe the horizon needs a tad of adjustment.</td>', 'Splendid capture that exudes a feeling of great tranquility. Maybe the horizon needs a tad of adjustment.', '2008-10-22 12:45:07.000000', NULL, 1),
(5020407, 731759, 99263, '<td valign="top">Absolutely stunning capture. I really love this one and as far as I am concerned this one should get a ribbon. Wonderful muted colors and play of light. The composition is also almost technically perfect except for the branches intruding into the top of the frame but that''s a minor niggle. The stance of the deer, it''s mouth open in calling is perfect and the tree and ferns in front create a nice natural frame.</td>', 'Absolutely stunning capture. I really love this one and as far as I am concerned this one should get a ribbon. Wonderful muted colors and play of light. The composition is also almost technically perfect except for the branches intruding into the top of the frame but that''s a minor niggle. The stance of the deer, it''s mouth open in calling is perfect and the tree and ferns in front create a nice natural frame.', '2008-10-22 12:53:35.000000', NULL, 1),
(5020408, 732201, 99263, '<td valign="top">Delightful image.</td>', 'Delightful image.', '2008-10-22 12:54:14.000000', NULL, 1),
(5020411, 731582, 99263, '<td valign="top">Lovely capture. I like your minimalistic background and bokeh and the detail and color of the bird are super. The red berries create a nice contrast and the single berry in the birds beak is the proverbial berry on top.</td>', 'Lovely capture. I like your minimalistic background and bokeh and the detail and color of the bird are super. The red berries create a nice contrast and the single berry in the birds beak is the proverbial berry on top.', '2008-10-22 12:58:56.000000', NULL, 1),
(5020421, 732220, 99263, '<td valign="top">What a super clear and detailed study of these trout. I like the way the light reflects of the bottom and off the trouts bodies. The frothy patches on the surface coupled with the way the light reflects creates just the right amount of contrast and reinforces the sensation of a slight swell on the surface.</td>', 'What a super clear and detailed study of these trout. I like the way the light reflects of the bottom and off the trouts bodies. The frothy patches on the surface coupled with the way the light reflects creates just the right amount of contrast and reinforces the sensation of a slight swell on the surface.', '2008-10-22 13:06:07.000000', NULL, 1),
(5020424, 732153, 99263, '<td valign="top">Great study of our distant (or maybe not so distant) cousin.Looks like he''s thinking hmmmmmmm.....</td>', 'Great study of our distant (or maybe not so distant) cousin.Looks like he''s thinking hmmmmmmm.....', '2008-10-22 13:08:01.000000', NULL, 1),
(5020429, 731728, 99263, '<td valign="top">Great composition and eye blinding colors.</td>', 'Great composition and eye blinding colors.', '2008-10-22 13:11:07.000000', NULL, 1),
(5020432, 732147, 99263, '<td valign="top">Cute little fellow and a lovely capture.</td>', 'Cute little fellow and a lovely capture.', '2008-10-22 13:12:25.000000', NULL, 1),
(5020434, 732020, 99263, '<td valign="top">Splendid capture for it''s simplicity and composition.</td>', 'Splendid capture for it''s simplicity and composition.', '2008-10-22 13:14:25.000000', NULL, 1),
(5020436, 731878, 99263, '<td valign="top">Stunning shot. Fantastic detail and lovely bokeh.</td>', 'Stunning shot. Fantastic detail and lovely bokeh.', '2008-10-22 13:16:07.000000', NULL, 1),
(5020437, 731169, 99263, '<td valign="top">Impressive shot of this wildfire.</td>', 'Impressive shot of this wildfire.', '2008-10-22 13:16:59.000000', NULL, 1),
(5020439, 731988, 99263, '<td valign="top">Wonderful capture. Grace and beauty radiate from this image.</td>', 'Wonderful capture. Grace and beauty radiate from this image.', '2008-10-22 13:18:22.000000', NULL, 1),
(5020441, 732101, 99263, '<td valign="top">You really captured the innocence and cuteness of this little chap in a special way. Lovely.</td>', 'You really captured the innocence and cuteness of this little chap in a special way. Lovely.', '2008-10-22 13:19:32.000000', NULL, 1),
(5020447, 732037, 99263, '<td valign="top">Excellent capture and composition. I love the soft pastel greens and fawn-brown colors. Lovely dof with just the right amount of detail in the main subject. It''s also great how you got him just as he was looking you right in the lens.</td>', 'Excellent capture and composition. I love the soft pastel greens and fawn-brown colors. Lovely dof with just the right amount of detail in the main subject. It''s also great how you got him just as he was looking you right in the lens.', '2008-10-22 13:23:14.000000', NULL, 1),
(5020449, 732269, 99263, '<td valign="top">Nice shot and I like the humor.</td>', 'Nice shot and I like the humor.', '2008-10-22 13:23:55.000000', NULL, 1),
(5020455, 732248, 99263, '<td valign="top">Very interesting and abstract image you present us with here. I like it.</td>', 'Very interesting and abstract image you present us with here. I like it.', '2008-10-22 13:25:42.000000', NULL, 1),
(5020460, 731886, 99263, '<td valign="top">Superb capture of this predator on the prowl. It''s like he almost comes at you out of the frame. The detail in his head is perfect and the background bokeh also. You really managed to capture that intent expression of being on the hunt in his face. And it works extremely well in black and white.</td>', 'Superb capture of this predator on the prowl. It''s like he almost comes at you out of the frame. The detail in his head is perfect and the background bokeh also. You really managed to capture that intent expression of being on the hunt in his face. And it works extremely well in black and white.', '2008-10-22 13:29:00.000000', NULL, 1),
(5020466, 732301, 99263, '<td valign="top">Lovely composition. I like the way the branches are arranged in the image and how you captured the parrot with wings outstretched as he is about to land. Nice subdued colors and tones.</td>', 'Lovely composition. I like the way the branches are arranged in the image and how you captured the parrot with wings outstretched as he is about to land. Nice subdued colors and tones.', '2008-10-22 13:31:43.000000', NULL, 1),
(5020476, 732299, 99263, '<td valign="top">The emerald green water forms an incredible backdrop for this mandarin duck.</td>', 'The emerald green water forms an incredible backdrop for this mandarin duck.', '2008-10-22 13:40:27.000000', NULL, 1),
(5020477, 731662, 99263, '<td valign="top">Lovely beach sunset with</td>', 'Lovely beach sunset with', '2008-10-22 13:41:01.000000', NULL, 1),
(5020483, 732109, 99263, '<td valign="top">Nice humorous giraffe capture.</td>', 'Nice humorous giraffe capture.', '2008-10-22 13:43:29.000000', NULL, 1),
(5020486, 731020, 99263, '<td valign="top">Delightful shot. I like the little guys inquisitive look.</td>', 'Delightful shot. I like the little guys inquisitive look.', '2008-10-22 13:44:46.000000', NULL, 1),
(5020490, 732015, 99263, '<td valign="top">Sure is close...too close for comfort. He has that "you are going to be my dinner" kind of look in his eyes.</td>', 'Sure is close...too close for comfort. He has that "you are going to be my dinner" kind of look in his eyes.', '2008-10-22 13:46:02.000000', NULL, 1),
(5020494, 731663, 99263, '<td valign="top">Visually stunning capture. Perfect dof and exquisite detail.</td>', 'Visually stunning capture. Perfect dof and exquisite detail.', '2008-10-22 13:46:59.000000', NULL, 1),
(5020497, 732075, 99263, '<td valign="top">Don''t know what it is exactly but this shot appeals to me a lot. The simplicity and mood it conveys maybe. Something about that lonely solitary pigeon. I like your title too.</td>', 'Don''t know what it is exactly but this shot appeals to me a lot. The simplicity and mood it conveys maybe. Something about that lonely solitary pigeon. I like your title too.', '2008-10-22 13:49:35.000000', NULL, 1),
(5020501, 731651, 99263, '<td valign="top">This shot has all the makings of being a really great shot. What detracts here is the piece of woody branch in the foreground and the 2 gaps allowing the light through in the background. For the rest the shot is absolutely amazing with nice fine detail.</td>', 'This shot has all the makings of being a really great shot. What detracts here is the piece of woody branch in the foreground and the 2 gaps allowing the light through in the background. For the rest the shot is absolutely amazing with nice fine detail.', '2008-10-22 13:52:59.000000', NULL, 1),
(5020505, 730806, 81530, '<td valign="top">Great shot! Good luck - No Vote</td>', 'Great shot! Good luck - No Vote', '2008-10-22 13:54:01.000000', NULL, 1),
(5020507, 731020, 81530, '<td valign="top">Oh my he is cute.</td>', 'Oh my he is cute.', '2008-10-22 13:54:20.000000', NULL, 1),
(5020517, 732163, 99263, '<td valign="top">Great capture of this bold and proud raptor. Super detail and lovely bokeh.</td>', 'Great capture of this bold and proud raptor. Super detail and lovely bokeh.', '2008-10-22 13:57:55.000000', NULL, 1),
(5020520, 732247, 99263, '<td valign="top">Very captivating capture. I like the soft white and gray hues and the way the main gull is lined up in the center with the rest of his flock lined up behind him with just the right amount of dof to render them a bit out of focus.</td>', 'Very captivating capture. I like the soft white and gray hues and the way the main gull is lined up in the center with the rest of his flock lined up behind him with just the right amount of dof to render them a bit out of focus.', '2008-10-22 14:01:18.000000', NULL, 1),
(5020523, 732150, 99263, '<td valign="top">Hmmmmm nice peaceful image with soft warm colors of autumn. Lovely.</td>', 'Hmmmmm nice peaceful image with soft warm colors of autumn. Lovely.', '2008-10-22 14:02:47.000000', NULL, 1),
(5020524, 732181, 99263, '<td valign="top">Exquisite capture. Only little niggle would be the intrusion of the bit of branch and leaf into the frame on the left hand side.</td>', 'Exquisite capture. Only little niggle would be the intrusion of the bit of branch and leaf into the frame on the left hand side.', '2008-10-22 14:04:18.000000', NULL, 1),
(5020530, 732230, 99263, '<td valign="top">Superlative shot of this gull and it is very effective in black and white. Love the way you got him as he was stretching. Indeed a pose like a dancer. Maybe you could have cropped just a little bit less tight on the left so that there would be a bit more space behind the wingtip. But that''s a minor little niggle.</td>', 'Superlative shot of this gull and it is very effective in black and white. Love the way you got him as he was stretching. Indeed a pose like a dancer. Maybe you could have cropped just a little bit less tight on the left so that there would be a bit more space behind the wingtip. But that''s a minor little niggle.', '2008-10-22 14:07:48.000000', NULL, 1),
(5020545, 732286, 99263, '<td valign="top">Very, very nice and quite unusual. I like the way you chose to include the almost suburban background into the photo to great effect so creating a nice contrast between nature''s tranquility and suburbia. The image shows how these 2 worlds so far apart can co-exist. The soft subdued colors are nice and almost give the impression of a oil painting.</td>', 'Very, very nice and quite unusual. I like the way you chose to include the almost suburban background into the photo to great effect so creating a nice contrast between nature''s tranquility and suburbia. The image shows how these 2 worlds so far apart can co-exist. The soft subdued colors are nice and almost give the impression of a oil painting.', '2008-10-22 14:15:23.000000', NULL, 1),
(5020551, 731727, 99263, '<td valign="top">Great colors and composition.I love the way you caught the golden ripples and reflections in the water.</td>', 'Great colors and composition.I love the way you caught the golden ripples and reflections in the water.', '2008-10-22 14:18:08.000000', NULL, 1),
(5020553, 732294, 99263, '<td valign="top">Wonderful shot and fitting title.</td>', 'Wonderful shot and fitting title.', '2008-10-22 14:18:33.000000', NULL, 1),
(5020564, 731716, 99263, '<td valign="top">Visually stunning silhouette of this group of cormorants.</td>', 'Visually stunning silhouette of this group of cormorants.', '2008-10-22 14:20:24.000000', NULL, 1),
(5020572, 732208, 99263, '<td valign="top">Absolutely fantastic image. The way the swimming otter just breaks the surface of the otherwise perfectly still water has been captured beautifully.</td>', 'Absolutely fantastic image. The way the swimming otter just breaks the surface of the otherwise perfectly still water has been captured beautifully.', '2008-10-22 14:23:22.000000', NULL, 1),
(5020573, 732188, 81530, '<td valign="top">Great use of selective saturation to focus on a single subject.</td>', 'Great use of selective saturation to focus on a single subject.', '2008-10-22 14:23:41.000000', NULL, 1),
(5020574, 732252, 81530, '<td valign="top">Great detail.</td>', 'Great detail.', '2008-10-22 14:23:53.000000', NULL, 1),
