(5021296, 731329, 80096, '<td valign="top">Simply magnificent. 8</td>', 'Simply magnificent. 8', '2008-10-22 23:24:02.000000', NULL, 1),
(5021301, 732247, 7969, '<td valign="top">This to me, is a great example of a sort of ''ordinary'' choice of wildlife subject, but your composition is so delightful in combination with your DOF choice, it is really enjoyable shot. It is great how you got them to line up like that :  )<br/> I would highly recommend with wildlife subjects if you do not have catch lights in its eyes that you make the shot 100 or 200% and then take a small dodge brush maybe 4-5 and then dodge in a catch light usually there is a small light there and you can just increase it to be a bit stronger. Works with people too. <br/>Try it and see what you think :  )<br/>7</td>', 'This to me, is a great example of a sort of ''ordinary'' choice of wildlife subject, but your composition is so delightful in combination with your DOF choice, it is really enjoyable shot. It is great how you got them to line up like that :  ) I would highly recommend with wildlife subjects if you do not have catch lights in its eyes that you make the shot 100 or 200% and then take a small dodge brush maybe 4-5 and then dodge in a catch light usually there is a small light there and you can just increase it to be a bit stronger. Works with people too. Try it and see what you think :  )7', '2008-10-22 23:29:31.000000', NULL, 1),
(5021302, 732140, 80096, '<td valign="top">Wonderful textures and detail. Nice overall composition. 7</td>', 'Wonderful textures and detail. Nice overall composition. 7', '2008-10-22 23:29:56.000000', NULL, 1),
