(5021715, 732147, 23300, '<td valign="top">Just beautiful! The word "serendipity" sprung to mind as soon as this image loaded. I looked up the meaning: serendipity - an aptitude for making desirable discoveries by accident. 10</td>', 'Just beautiful! The word "serendipity" sprung to mind as soon as this image loaded. I looked up the meaning: serendipity - an aptitude for making desirable discoveries by accident. 10', '2008-10-23 02:52:47.000000', NULL, 1),
(5021720, 731020, 54645, '<td valign="top">Hello Theodore!!!<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=719635" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/54645/120/719635.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/54645/120/719635.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/54645/120/719635.jpg"/></a> <br/><br/><br/><i>Message edited by author 2008-10-27 00:06:53.</i></td>', 'Hello Theodore!!! ', '2008-10-23 02:58:25.000000', '2008-10-27 00:06:53.000000', 1),
(5021727, 732240, 23300, '<td valign="top">An impressive capture. My only niggle is that the motion blur on the wings is little too extreme for my liking.</td>', 'An impressive capture. My only niggle is that the motion blur on the wings is little too extreme for my liking.', '2008-10-23 03:05:18.000000', NULL, 1),
