(5023649, 731421, 67258, '<td valign="top">The placement of the pelican against the blue of the sky, with the clouds subtly framing works well.</td>', 'The placement of the pelican against the blue of the sky, with the clouds subtly framing works well.', '2008-10-24 16:50:44.000000', NULL, 1),
(5023656, 731022, 67258, '<td valign="top">Strong composition, and good choice of dof - I might have preferred just a little looser framing top and bottom, and with marginally more room to the left</td>', 'Strong composition, and good choice of dof - I might have preferred just a little looser framing top and bottom, and with marginally more room to the left', '2008-10-24 16:53:23.000000', NULL, 1),
