(5024109, 731880, 70650, '<td valign="top">Very nice capture &amp; nicely produced. 2 thumbs up!</td>', 'Very nice capture & nicely produced. 2 thumbs up!', '2008-10-25 00:04:30.000000', NULL, 1),
(5024260, 732020, 66616, '<td valign="top">nice work</td>', 'nice work', '2008-10-25 03:18:44.000000', NULL, 1),
(5024269, 732214, 67258, '<td valign="top">That moment of coming across an animal as large as a deer is quite magical - and that comes across in this photo.  There may be motion blur from a bit of camera shake, the focus maybe off a tad, and the composition could be better, but the sense of immediacy, of stumbling upon a part of our world that we are not normally privileged to witness is all there.</td>', 'That moment of coming across an animal as large as a deer is quite magical - and that comes across in this photo.  There may be motion blur from a bit of camera shake, the focus maybe off a tad, and the composition could be better, but the sense of immediacy, of stumbling upon a part of our world that we are not normally privileged to witness is all there.', '2008-10-25 03:42:21.000000', NULL, 1),
(5024270, 732247, 66616, '<td valign="top">nice work</td>', 'nice work', '2008-10-25 03:50:53.000000', NULL, 1),
