(5024290, 732208, 66616, '<td valign="top">great shot</td>', 'great shot', '2008-10-25 04:52:49.000000', NULL, 1),
(5024295, 731868, 66616, '<td valign="top">nice shot, well composed</td>', 'nice shot, well composed', '2008-10-25 05:09:42.000000', NULL, 1),
(5024296, 731727, 66616, '<td valign="top">this is my favourite so far, well done!</td>', 'this is my favourite so far, well done!', '2008-10-25 05:10:12.000000', NULL, 1),
(5024297, 732188, 66616, '<td valign="top">I find this too busy, nothing to focus on.</td>', 'I find this too busy, nothing to focus on.', '2008-10-25 05:10:45.000000', NULL, 1),
