(5026011, 731798, 83416, '<td valign="top">Beautiful shot!!! Great the colors and composition. Only comment  maybe a bit dark in the eye are. Believe should do very well at roll-over.</td>', 'Beautiful shot!!! Great the colors and composition. Only comment  maybe a bit dark in the eye are. Believe should do very well at roll-over.', '2008-10-26 20:04:24.000000', NULL, 1),
(5026014, 731759, 83416, '<td valign="top">One of the best in the challenge!!! Love the atmosphere of this shot  not to mention the color tones, composition, animals pose and post-processing.</td>', 'One of the best in the challenge!!! Love the atmosphere of this shot  not to mention the color tones, composition, animals pose and post-processing.', '2008-10-26 20:06:47.000000', NULL, 1),
