(5026026, 731619, 83416, '<td valign="top">Nice detail and that eye makes the shot! Good luck at roll-over.</td>', 'Nice detail and that eye makes the shot! Good luck at roll-over.', '2008-10-26 20:12:45.000000', NULL, 1),
