(5026176, 732208, 7969, '<td valign="top">This is sort of a typical shot, but the smoothness of the water and the shape of the water swirl along with the color tone I think makes it elegant.</td>', 'This is sort of a typical shot, but the smoothness of the water and the shape of the water swirl along with the color tone I think makes it elegant.', '2008-10-26 22:10:59.000000', NULL, 1),
(5026183, 732122, 94265, '<td valign="top">The focus and sharpness are brilliant, you can even see the lines of the iris in her eye. I like the neutral background too.</td>', 'The focus and sharpness are brilliant, you can even see the lines of the iris in her eye. I like the neutral background too.', '2008-10-26 22:17:28.000000', NULL, 1),
(5026191, 732294, 94265, '<td valign="top">Cool angle, I love that the sun has kinda backlit his wings.</td>', 'Cool angle, I love that the sun has kinda backlit his wings.', '2008-10-26 22:26:35.000000', NULL, 1),
(5026193, 732288, 94265, '<td valign="top">Took me a while to find the deer when I first saw this. I like the natural skyline and the colour of the sky is just beautiful.</td>', 'Took me a while to find the deer when I first saw this. I like the natural skyline and the colour of the sky is just beautiful.', '2008-10-26 22:28:16.000000', NULL, 1),
(5026194, 732015, 73250, '<td valign="top">I think, this would look so much better b/w. The colors are so off, they are distracting. There is some really nice texture and the comp works well.</td>', 'I think, this would look so much better b/w. The colors are so off, they are distracting. There is some really nice texture and the comp works well.', '2008-10-26 22:28:32.000000', NULL, 1),
(5026197, 731020, 94265, '<td valign="top">This earns an easy 10 from me, great focus and perfect composition. He''s so cute too! I think we''ve got a ribboner here.</td>', 'This earns an easy 10 from me, great focus and perfect composition. He''s so cute too! I think we''ve got a ribboner here.', '2008-10-26 22:30:04.000000', NULL, 1),
