(5026313, 731582, 45475, '<td valign="top">Congratulations on the great finish Sarah!! I knew this would do well. :)</td>', 'Congratulations on the great finish Sarah!! I knew this would do well. :)', '2008-10-27 00:07:47.000000', NULL, 0),
(5026314, 732181, 67697, '<td valign="top">I thought this was adorable and a great catch.  Wonderful clarity and DOF.  Congrats on your new PB!</td>', 'I thought this was adorable and a great catch.  Wonderful clarity and DOF.  Congrats on your new PB!', '2008-10-27 00:08:11.000000', NULL, 0),
(5026318, 732288, 67697, '<td valign="top">I thought this was cool.  I loved the silhouette of the deer in the corner.  The sky is gorgeous too.</td>', 'I thought this was cool.  I loved the silhouette of the deer in the corner.  The sky is gorgeous too.', '2008-10-27 00:09:25.000000', NULL, 0),
