(5026322, 732247, 54645, '<td valign="top">This was clearly the best image in the challenge. I can''t tell you how many times I came back to look at it! Well done. 10 from me.</td>', 'This was clearly the best image in the challenge. I can''t tell you how many times I came back to look at it! Well done. 10 from me.', '2008-10-27 00:10:52.000000', NULL, 0),
(5026323, 730572, 67697, '<td valign="top">I liked the border on this.  It reminds me of a card, maybe a Christmas card if there were some snow lol.  I like how the softness of the border just kind of blended in with the background.  Pretty!</td>', 'I liked the border on this.  It reminds me of a card, maybe a Christmas card if there were some snow lol.  I like how the softness of the border just kind of blended in with the background.  Pretty!', '2008-10-27 00:11:39.000000', NULL, 0),
(5026326, 732163, 54645, '<td valign="top">Wonderful photograph, I figured this and the other eagle would be in the top 5. (No idea I would split them though!) Congrats on the ribbon!</td>', 'Wonderful photograph, I figured this and the other eagle would be in the top 5. (No idea I would split them though!) Congrats on the ribbon!', '2008-10-27 00:12:25.000000', NULL, 0),
(5026328, 732300, 65319, '<td valign="top">I''m one of your 4 ten votes.  I just loved this little guy and am disappointed for you to see this placement.</td>', 'I''m one of your 4 ten votes.  I just loved this little guy and am disappointed for you to see this placement.', '2008-10-27 00:13:26.000000', NULL, 0),
(5026329, 731759, 6845, '<td valign="top">All right another top ten, but seriously now, quit wasting all these good scores on non oly challenges.  =)</td>', 'All right another top ten, but seriously now, quit wasting all these good scores on non oly challenges.  =)', '2008-10-27 00:13:39.000000', NULL, 0),
(5026330, 732075, 67697, '<td valign="top">Ha!  I knew it as yours - but was too chicken to post it.  What I loved about this was that it was more than just a shot of an animal.  There was some kind of story to be told, and it was up to the viewer to decide what was going on.  The black and white treatment is very fitting for the mood of the shot.</td>', 'Ha!  I knew it as yours - but was too chicken to post it.  What I loved about this was that it was more than just a shot of an animal.  There was some kind of story to be told, and it was up to the viewer to decide what was going on.  The black and white treatment is very fitting for the mood of the shot.', '2008-10-27 00:13:40.000000', NULL, 0),
(5026332, 732247, 97166, '<td valign="top">Hrmm. One of my very elusive 10 votes (I think I''ve given out like five of them in 3 months), is actually a blue ribbon winner.<br/> <br/>I''ve become mainstream.<br/> <br/>I cry.</td>', 'Hrmm. One of my very elusive 10 votes (I think I''ve given out like five of them in 3 months), is actually a blue ribbon winner. I''ve become mainstream. I cry.', '2008-10-27 00:14:04.000000', NULL, 0),
(5026334, 730892, 67697, '<td valign="top">That''s too bad it scored so low.  I thought it was a good environmental shot AND quite funny.</td>', 'That''s too bad it scored so low.  I thought it was a good environmental shot AND quite funny.', '2008-10-27 00:14:57.000000', NULL, 0),
(5026338, 732049, 67697, '<td valign="top">I really liked this one.  I thought it was cool that the darkness of the bird popped out from the brightly blended background.</td>', 'I really liked this one.  I thought it was cool that the darkness of the bird popped out from the brightly blended background.', '2008-10-27 00:16:06.000000', NULL, 0),
(5026339, 732299, 51747, '<td valign="top">Congrats on your top 20 finish Rob! A very nice pic indeed!</td>', 'Congrats on your top 20 finish Rob! A very nice pic indeed!', '2008-10-27 00:16:27.000000', NULL, 0),
(5026340, 731728, 70270, '<td valign="top">lol -- top 10, with a wooden duck!  I gave you a 3 ... great photo, kind of wild, but no "life".  The eye gave this away as a decoy.  If I''m wrong, and this is a real duck, I owe you a big apology.  Either way, congrats on a great finish in this challenge!</td>', 'lol -- top 10, with a wooden duck!  I gave you a 3 ... great photo, kind of wild, but no "life".  The eye gave this away as a decoy.  If I''m wrong, and this is a real duck, I owe you a big apology.  Either way, congrats on a great finish in this challenge!', '2008-10-27 00:16:56.000000', NULL, 0),
(5026342, 732036, 67697, '<td valign="top">Loved the title and the colors are gorgeous!  The lighting looks like it was just right for this.  Too bad it was so camera shy lol.</td>', 'Loved the title and the colors are gorgeous!  The lighting looks like it was just right for this.  Too bad it was so camera shy lol.', '2008-10-27 00:18:36.000000', NULL, 0),
(5026346, 732247, 30982, '<td valign="top">Congratulations!  This is such a fun and delightful shot - I''m very pleased to see this win the blue!  Alternate title - Leader of the Pack.  I also get a kick out of how he appears rather cross-eyed.</td>', 'Congratulations!  This is such a fun and delightful shot - I''m very pleased to see this win the blue!  Alternate title - Leader of the Pack.  I also get a kick out of how he appears rather cross-eyed.', '2008-10-27 00:20:41.000000', NULL, 0),
(5026352, 732075, 3214, '<td valign="top">Nice storytelling, even without the title.</td>', 'Nice storytelling, even without the title.', '2008-10-27 00:22:05.000000', NULL, 0),
(5026354, 732243, 1031, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Jedusi:</b></div><hr/><i> Nice placing of the Heron in the shot - but the huge lump of wood is just too distracting for me.<br/> <br/>Unfortunately the eye naturally gets drawn to brighter areas of an image and you clearly want people looking at the bird and not the wood. One answer would have been to spot edit it and tone it down, so it is still there - just darker. </i></td></tr></table> <br/>I am so used to using Basic editing for most all my entries I didn''t even think of selectively darkening the wood, though I made a quick attempt at it when I read your comment (see below). I did consider entering the unadjusted cropped version, but I decided it was important to include the water.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=733922" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/0-4999/1031/120/733922.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/0-4999/1031/120/733922.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/0-4999/1031/120/733922.jpg"/></a> <a href="//www.dpchallenge.com/image.php?IMAGE_ID=733923" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/0-4999/1031/120/733923.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/0-4999/1031/120/733923.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/0-4999/1031/120/733923.jpg"/></a></td>', 'Originally posted by Jedusi: Nice placing of the Heron in the shot - but the huge lump of wood is just too distracting for me. Unfortunately the eye naturally gets drawn to brighter areas of an image and you clearly want people looking at the bird and not the wood. One answer would have been to spot edit it and tone it down, so it is still there - just darker.  I am so used to using Basic editing for most all my entries I didn''t even think of selectively darkening the wood, though I made a quick attempt at it when I read your comment (see below). I did consider entering the unadjusted cropped version, but I decided it was important to include the water.  ', '2008-10-27 00:22:43.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5026358, 731582, 44877, '<td valign="top">Hotdamn! Top 20 - totally awesome, Sarah!! Beautiful photo. I''m so happy for you!!!<br/> <br/></td>', 'Hotdamn! Top 20 - totally awesome, Sarah!! Beautiful photo. I''m so happy for you!!! ', '2008-10-27 00:25:17.000000', NULL, 0),
