(5026379, 732181, 30982, '<td valign="top">Huge congrats on the new Personal Best!!  Love the light in this shot, and the background is lovely - really shows off your widdle wed squirrel very well!</td>', 'Huge congrats on the new Personal Best!!  Love the light in this shot, and the background is lovely - really shows off your widdle wed squirrel very well!', '2008-10-27 00:35:08.000000', NULL, 0),
(5026381, 732264, 68947, '<td valign="top">Congrats on the brown!  Display it proudly on your bio page!  It was a humorous shot and for those who say that this didn''t fit the challenge...they haven''t met certain types of men, have they? ;)</td>', 'Congrats on the brown!  Display it proudly on your bio page!  It was a humorous shot and for those who say that this didn''t fit the challenge...they haven''t met certain types of men, have they? ;)', '2008-10-27 00:36:09.000000', NULL, 0),
(5026382, 732273, 75585, '<td valign="top">I thought this was done in a zoo - but I am not a purist (evidenced by my shot) and loved this one too.</td>', 'I thought this was done in a zoo - but I am not a purist (evidenced by my shot) and loved this one too.', '2008-10-27 00:36:22.000000', NULL, 0),
(5026383, 731789, 16046, '<td valign="top">Way underrated, should have ribboned.</td>', 'Way underrated, should have ribboned.', '2008-10-27 00:36:36.000000', NULL, 0),
(5026384, 732247, 75585, '<td valign="top">Congrats - this is a great capture and the composition was spot one - way to go a deserved blue!!</td>', 'Congrats - this is a great capture and the composition was spot one - way to go a deserved blue!!', '2008-10-27 00:37:27.000000', NULL, 0),
