(5027116, 732247, 86447, '<td valign="top">I smile every time I look at your BLUE RIBBON image.  Congrats, Karen!</td>', 'I smile every time I look at your BLUE RIBBON image.  Congrats, Karen!', '2008-10-27 12:13:51.000000', NULL, 0),
