(5027248, 732135, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677021" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg"/></a>PostLuminous Award Nominee!<br/>exceptionally well done.  I especially like the "echo" of the wavy texture from coat to stone</td>', 'PostLuminous Award Nominee!exceptionally well done.  I especially like the "echo" of the wavy texture from coat to stone', '2008-10-27 13:14:02.000000', NULL, 0),
