(5028982, 732230, 59029, '<td valign="top">I really love this shot, so simple and elegant, excellent use of negative space and looks great in b/w.  Really can''t see any way to improve on it!</td>', 'I really love this shot, so simple and elegant, excellent use of negative space and looks great in b/w.  Really can''t see any way to improve on it!', '2008-10-28 12:18:49.000000', NULL, 0),
(5028987, 730572, 59029, '<td valign="top">Normally I''m not a border person, but I do like this one here, very soft and effective, and the single branch in the bg gives it a great sense of dof.  And the lighting is amazing.  Great shot!</td>', 'Normally I''m not a border person, but I do like this one here, very soft and effective, and the single branch in the bg gives it a great sense of dof.  And the lighting is amazing.  Great shot!', '2008-10-28 12:21:11.000000', NULL, 0),
